  function renderText(target, text) {
    const blocks = text.split(/\n\s*\n/);
    for (const block of blocks) {
      if (!block.trim()) continue;
      const line = block.trim();
      if (/^!\[[^\]]*\]\([^)]*\)$/.test(line)) {
        const image = document.createElement("img");
        image.src = "Daniel_Aspelin_Kodeksi_logo.png";
        image.alt = "Kodeksi-logo";
        image.style.cssText = "display:block;max-width:160px;height:auto;margin:1rem auto";
        target.appendChild(image);
        continue;
      }
      const el = document.createElement(line.startsWith("# ") ? "h3" : "p");
      el.textContent = line.replace(/^# /, "");
      target.appendChild(el);
    }
  }
  groups.forEach((group, i) => {
    const parent = document.createElement("details");
    const summary = document.createElement("summary");
    summary.textContent = String(i).padStart(2, "0") + " — " + group.title;
    parent.appendChild(summary);
    parent.open = true;
    group.files.forEach((file) => {
      const child = document.createElement("details");
      const title = document.createElement("summary");
      title.textContent = file.name;
      child.appendChild(title);
      const content = document.createElement("div");
      content.className = "content";
      renderText(content, file.text);
      child.appendChild(content);
      parent.appendChild(child);
    });
    section.appendChild(parent);
  });
  const link = document.createElement("a");
  link.className = "source-link";
  link.href = "Daniel_Aspelin_Kodeksi_v1.5.md";
  link.textContent = "Alkuperäinen lähdeasiakirja (Markdown)";
  section.appendChild(link);
  const main = document.querySelector("main");
